select from safety_employee_message where status = 'NORMAL'
and emp_name like concat('%',#{empName},'%')
and (emp_name like concat('%',#{empNoAndName},'%') or emp_no = #{empNoAndName})
and find_in_set(#{orgCode},org_code_path) > 0
and org_code_path like CONCAT(#{orgPathCode},'%')
and emp_no not like concat(#{noEmpNoStart},'%')
order by ${orderByClause}
limit ${offset}, ${limit}
limit ${limit}

select ${fieldName}
from safety_employee_message
where status = 'NORMAL'
group by ${fieldName}
